function findTheLongestBalancedSubstring(s) {
  let best = 0;
  let zeros = 0;
  let ones = 0;

  for (const ch of s) {
    if (ch === '0') {
      if (ones > 0) {
        zeros = 0;
        ones = 0;
      }
      zeros++;
    } else {
      ones++;
      best = Math.max(best, 2 * Math.min(zeros, ones));
    }
  }
  return best;
}

