function findTheLongestBalancedSubstring(s) {
  let answer = 0;
  for (let start = 0; start < s.length; start++) {
    for (let end = start + 2; end <= s.length; end += 2) {
      const piece = s.slice(start, end);
      const half = piece.length / 2;
      if (piece === '0'.repeat(half) + '1'.repeat(half)) answer = Math.max(answer, piece.length);
    }
  }
  return answer;
}

