function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const length = size === 'large' ? 50 : pick(1, 12);
  if (rand() < 0.35) {
    let s = '';
    for (let i = 0; i < length; i++) s += rand() < 0.5 ? '0' : '1';
    return [s];
  }
  // Build the string from runs so long blocks of zeros and ones appear.
  const longest = size === 'large' ? 15 : 5;
  let s = '';
  let digit = rand() < 0.5 ? '0' : '1';
  while (s.length < length) {
    s += digit.repeat(pick(1, longest));
    digit = digit === '0' ? '1' : '0';
  }
  return [s.slice(0, length)];
}
